{
  "name": "opencode-vision-router",
  "version": "0.2.2",
  "description": "Route pasted images to a cheap vision model in opencode so text-only main agents work from its text output.",
  "type": "module",
  "main": "dist/index.js",
  "exports": "./dist/index.js",
  "files": ["dist"],
  "keywords": ["opencode", "opencode-plugin", "vision", "multimodal", "subagent"],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Chathula/opencode-vision-router.git"
  },
  "homepage": "https://github.com/Chathula/opencode-vision-router#readme",
  "bugs": {
    "url": "https://github.com/Chathula/opencode-vision-router/issues"
  },
  "scripts": {
    "test": "bun test",
    "build": "bun build src/index.ts --outfile dist/index.js --target=node --external @opencode/plugin"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.22"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.34",
    "@opencode-ai/sdk": "^1.18.34",
    "@types/bun": "^1.4.2",
    "typescript": "^7.0.2"
  }
}
